type Cache struct {
    mu   sync.RWMutex
    data map[string]*entry
}
func (c *Cache) Get(k string) (*entry, bool) {
    c.mu.RLock()
    e, ok := c.data[k]
    c.mu.RUnlock()
    if ok && e.expired() {
        go c.refresh(k)          // spawned on every expired read
    }
    return e, ok
}
func (c *Cache) refresh(k string) {
    v := load(k)                 // may block forever, no ctx
    c.data[k] = &entry{v: v, exp: time.Now().Add(ttl)}
}
