from functools import lru_cache

@lru_cache(maxsize=None)
def count_paths(grid_key, r, c):
    grid = decode(grid_key)       # O(n*m) parse each call
    if r == len(grid) or c == len(grid[0]) or grid[r][c] == 1:
        return 0
    if r == len(grid) - 1 and c == len(grid[0]) - 1:
        return 1
    return count_paths(grid_key, r + 1, c) + count_paths(grid_key, r, c + 1)
